.hy_rows<-function(x,name){if(!is.list(x)||!length(x)||!is.null(names(x))||any(!vapply(x,.cr_object,logical(1)))) .cr_error('HYBRID_CONTRACT',paste(name,'requires records'));x}
.hy_dates<-function(as_of,known_at,context=NULL){a<-.cr_data_date(as_of,'as_of');k<-.cr_data_date(known_at,'known_at');ctx<-.cr_result(NULL,'hybrid.context',context=context)$context;if(k>a) .cr_error('HYBRID_LOOKAHEAD','Forecast information cannot be known after forecast date');for(key in c('as_of','known_at')){value<-if(key=='as_of')as_of else known_at;if(!is.null(ctx[[key]])&&!identical(ctx[[key]],value)) .cr_error('TARGET_MISMATCH','Signal dates differ from context')};list(as_of=a,known_at=k)}
combine_pd_signals<-function(pd_signals,weights,combination_scale,combination_contract,context=NULL) {
 signals<-.hy_rows(pd_signals,'pd_signals');ids<-.ex_ids(lapply(signals,function(r)r$signal_id),'signal_ids');contract<-.ex_object(combination_contract,'combination_contract');target<-.ex_target(signals[[1]]$target,context);rows<-.ex_ids(signals[[1]]$row_ids,'row_ids');n<-length(rows);m<-length(signals);values<-list()
 for(signal in signals){if(!identical(.cr_hash(signal$target),.cr_hash(target))||!identical(.ex_ids(signal$row_ids,'row_ids'),rows)||!identical(signal$as_of,signals[[1]]$as_of)||!identical(signal$known_at,signals[[1]]$known_at)) .cr_error('HYBRID_ALIGNMENT','Signals need identical target, ordered rows and dates');.hy_dates(signal$as_of,signal$known_at,context);for(k in c('model_id','model_version')).cr_string(signal[[k]],k,'HYBRID_CONTRACT');p<-.ex_vec(signal$pd,'pd');if(length(p)!=n||any(p<0|p>1)) .cr_error('HYBRID_PROBABILITY','Valid aligned probabilities required');values[[length(values)+1L]]<-p}
 p<-do.call(cbind,values);interpretation<-c(linear='estimator_pool',log_odds='log_odds_pool',mixture='latent_regime_mixture');if(!(combination_scale%in%names(interpretation))||!identical(contract$interpretation,unname(interpretation[combination_scale]))) .cr_error('HYBRID_INTERPRETATION','Compatible combination interpretation required');.cr_string(contract$reference,'reference','HYBRID_INTERPRETATION')
 if(combination_scale=='mixture'){w<-.ex_matrix(weights,'weights');if(!identical(dim(w),c(n,m))||!identical(.ex_ids(contract$regime_ids,'regime_ids'),ids)||!identical(contract$conditional_regime_probabilities,TRUE)) .cr_error('HYBRID_MIXTURE','Row-specific conditional regime probabilities and IDs required')}else{w<-.ex_vec(weights,'weights');if(length(w)!=m) .cr_error('HYBRID_WEIGHT','One weight per signal required');w<-matrix(rep(w,each=n),n,m)}
 maxima<-apply(w,1,max);if(any(w<0)||any(maxima<=0)) .cr_error('HYBRID_WEIGHT','Nonnegative weights and positive totals required');w<-w/maxima;w<-w/rowSums(w);status<-rep('INTERIOR',n);log_odds<-NULL
 if(combination_scale=='log_odds'){zero<-rowSums((p==0)&(w>0))>0;one<-rowSums((p==1)&(w>0))>0;if(any(zero&one)) .cr_error('HYBRID_BOUNDARY_CONFLICT','Positive-weight zero and one signals give undefined pooled log odds');lp<-matrix(0,n,m);inside<-p>0&p<1;lp[inside]<-stats::qlogis(p[inside]);parts<-w*lp;eta<-rowSums(parts);combined<-stats::plogis(eta);combined[zero]<-0;combined[one]<-1;contributions<-lapply(seq_len(n),function(i)lapply(seq_len(m),function(j)if(p[i,j]%in%c(0,1)&&w[i,j]>0)NULL else parts[i,j]));log_odds<-lapply(seq_len(n),function(i)if(zero[i]||one[i])NULL else eta[i]);status<-ifelse(zero,'ZERO_LIMIT',ifelse(one,'ONE_LIMIT','INTERIOR'))}else{combined<-rowSums(w*p);contributions<-.ex_rows(w*p)}
 between<-rowSums(w*(p-combined)^2);within<-rowSums(w*p*(1-p))
 .cr_result(list(pd=as.list(combined),row_ids=as.list(rows),signal_ids=as.list(ids),combination_scale=combination_scale,combination_contract=contract,normalized_weights=.ex_rows(w),contributions=contributions,contribution_scale=if(combination_scale=='log_odds')'log_odds'else 'probability',combined_log_odds=log_odds,boundary_status=as.list(status),weighted_signal_dispersion=as.list(between),mixture_within_regime_variance=if(combination_scale=='mixture')as.list(within)else NULL,mixture_between_regime_variance=if(combination_scale=='mixture')as.list(between)else NULL,target=target,as_of=signals[[1]]$as_of,known_at=signals[[1]]$known_at,signal_fingerprints=as.list(vapply(signals,.cr_hash,character(1)))),'hybrid.combine_pd_signals','probability',context,limitations='Estimates refer to the same event and horizon; aggregation is not an event union. Mixture weights are supplied conditional regime probabilities; pool weights are explicit modeling choices. Dispersion is not a confidence interval or independent information.')
}
.hy_horizon_end<-function(start,target){d<-.cr_data_date(start,'as_of');h<-target$horizon;unit<-target$time_unit;if(unit=='days'){if(h!=floor(h)) .cr_error('HYBRID_HORIZON','Date windows need integer days');return(d+h)};months<-h*if(unit=='years')12 else 1;if(months!=floor(months)) .cr_error('HYBRID_HORIZON','Calendar windows need integer months');year<-as.integer(format(d,'%Y'));month<-as.integer(format(d,'%m'));day<-as.integer(format(d,'%d'));count<-year*12+month-1+months;year<-floor(count/12);month<-count%%12+1;if(year<1||year>9999) .cr_error('HYBRID_HORIZON','Unsupported calendar range');days<-c(31,if(year%%4==0&&(year%%100!=0||year%%400==0))29 else 28,31,30,31,30,31,31,30,31,30,31);as.Date(sprintf('%04d-%02d-%02d',as.integer(year),as.integer(month),min(day,days[month])))}
.hy_oof_contract<-function(split_plan,base_model_ids,target,training,outcomes){plan<-.ex_object(split_plan,'split_plan');rows<-.hy_rows(plan$rows,'split rows');folds<-.hy_rows(plan$folds,'folds');ids<-.ex_ids(lapply(rows,function(r)r$row_id),'row_ids');.ex_ids(lapply(folds,function(f)f$fold_id),'fold_ids');cutoff<-.cr_data_date(training$known_at,'training known_at');if(!identical(plan$horizon_date_rule,'calendar_clamp')) .cr_error('HYBRID_HORIZON','Declare calendar_clamp horizon convention')
 for(row in rows){for(k in c('entity_id','group_id')).cr_string(row[[k]],k,'HYBRID_SPLIT');if(!(row$role%in%c('development','calibration','test'))) .cr_error('HYBRID_SPLIT','Outer role required');.cr_data_date(row$as_of,'as_of')}
 for(pair in list(c('development','calibration'),c('development','test'),c('calibration','test')))for(key in c('entity_id','group_id')){left<-vapply(Filter(function(r)r$role==pair[1],rows),function(r)r[[key]],character(1));right<-vapply(Filter(function(r)r$role==pair[2],rows),function(r)r[[key]],character(1));if(length(intersect(left,right))) .cr_error('HYBRID_LEAKAGE','Outer role entity/group overlap')}
 mature<-function(i,at){row<-rows[[i]];value<-outcomes[[i]];if(!is.numeric(value)||length(value)!=1L||is.na(value)||!(value%in%c(0,1))) .cr_error('HYBRID_OUTCOME','Used labels must be binary numeric');origin<-.cr_data_date(row$as_of,'as_of');known<-.cr_data_date(row$label_known_at,'label_known_at');end<-.hy_horizon_end(row$as_of,target);if(known<origin||known>at||end>at) .cr_error('HYBRID_MATURITY','Used cohort must be horizon mature and label known at fit cutoff');if(value==0&&.cr_data_date(row$complete_through,'complete_through')<end) .cr_error('HYBRID_MATURITY','Negative labels need complete coverage')}
 heldout<-integer();fold_trace<-list()
 for(fold in folds){train<-.ex_ids(fold$train_row_ids,'train_row_ids');validation<-.ex_ids(fold$validation_row_ids,'validation_row_ids');if(length(setdiff(c(train,validation),ids))||length(intersect(train,validation))) .cr_error('HYBRID_SPLIT','Known disjoint training/validation rows required');tr<-match(train,ids);va<-match(validation,ids);if(any(vapply(rows[c(tr,va)],function(r)r$role!='development',logical(1)))||length(intersect(heldout,va))) .cr_error('HYBRID_LEAKAGE','Only development folds; one held-out prediction per row')
 for(key in c('entity_id','group_id'))if(length(intersect(vapply(rows[tr],function(r)r[[key]],character(1)),vapply(rows[va],function(r)r[[key]],character(1))))) .cr_error('HYBRID_LEAKAGE','Fold entity/group overlap')
 first<-min(as.Date(vapply(rows[va],function(r)r$as_of,character(1))));fit_at<-.cr_data_date(fold$fit_known_at,'fit_known_at');if(fit_at>=first) .cr_error('HYBRID_LEAKAGE','Fit must precede held-out forecasts');for(i in tr)mature(i,fit_at);for(i in va){mature(i,cutoff);if(.cr_data_date(rows[[i]]$prediction_known_at,'prediction_known_at')>.cr_data_date(rows[[i]]$as_of,'as_of')) .cr_error('HYBRID_LEAKAGE','Held-out forecast not known at forecast date')}
 lineage<-.ex_object(fold$base_lineage,'base_lineage');if(!setequal(names(lineage),base_model_ids)) .cr_error('HYBRID_LINEAGE','Fold lineage required for each base')
 for(base in base_model_ids){record<-.ex_object(lineage[[base]],'base lineage');if(!identical(record$model_id,base)||!identical(.cr_hash(record$target),.cr_hash(target))||!identical(record$prediction_origin,'HELD_OUT')) .cr_error('HYBRID_LINEAGE','Matching base ID/target and held-out origin required');for(k in c('model_version','training_fingerprint','reference')).cr_string(record[[k]],k,'HYBRID_LINEAGE');for(k in c('fit_row_ids','preprocessing_row_ids','selection_row_ids')){used<-.ex_ids(record[[k]],k,empty=k=='selection_row_ids');if(length(setdiff(used,train))) .cr_error('HYBRID_LEAKAGE','Base preprocessing/selection/fit includes nontraining rows')};base_known<-.cr_data_date(record$known_at,'base known_at');if(base_known>fit_at||any(base_known>as.Date(vapply(rows[va],function(r)r$prediction_known_at,character(1))))) .cr_error('HYBRID_LEAKAGE','Base artifact unavailable at fit/prediction cutoff');for(row_id in unique(c(unlist(record$fit_row_ids),unlist(record$selection_row_ids))))mature(match(row_id,ids),base_known)}
 heldout<-c(heldout,va);fold_trace[[length(fold_trace)+1L]]<-list(fold_id=fold$fold_id,train_row_ids=as.list(train),validation_row_ids=as.list(validation),lineage_fingerprint=.cr_hash(lineage),fit_known_at=fold$fit_known_at)
 }
 if(!length(heldout)) .cr_error('HYBRID_SPLIT','At least one mature held-out row required');list(rows=rows,used=sort(heldout),trace=fold_trace)
}
.hy_rawmatrix<-function(x){if(is.list(x)&&is.null(names(x))){sizes<-lengths(x);if(!length(x)||length(unique(sizes))!=1L) .cr_error('HYBRID_DATA','Rectangular prediction rows required');x<-do.call(rbind,lapply(x,function(r)vapply(r,function(v)if(is.null(v))NA_real_ else as.numeric(v),numeric(1))))};if(!is.matrix(x)||!is.numeric(x)) .cr_error('HYBRID_DATA','Numeric matrix with missing values only outside used OOF rows required');x}
fit_stacked_pd<-function(out_of_fold_base_predictions,outcomes,base_model_ids,split_plan,meta_model_spec,target,training,model_id,model_version,weights=NULL,context=NULL) {
 features<-.ex_ids(base_model_ids,'base_model_ids');target<-.ex_target(target,context);train<-.ex_object(training,'training');spec<-.ex_object(meta_model_spec,'meta_model_spec');x<-.hy_rawmatrix(out_of_fold_base_predictions);y<-as.list(outcomes)
 if(ncol(x)!=length(features)||length(y)!=nrow(x)||length(split_plan$rows)!=nrow(x)) .cr_error('HYBRID_DATA','Aligned predictions, outcomes, bases and split rows required');checked<-.hy_oof_contract(split_plan,features,target,train,y);rows<-checked$rows;used<-checked$used;p<-x[used,,drop=FALSE];labels<-vapply(y[used],as.numeric,numeric(1));if(any(!is.finite(p))||any(p<0|p>1)) .cr_error('HYBRID_PROBABILITY','Used OOF predictions must be finite probabilities');transform<-spec$input_scale;if(!(transform%in%c('probability','log_odds'))) .cr_error('HYBRID_META_MODEL','Declare probability or log_odds input_scale');if(transform=='log_odds'&&any(p==0|p==1)) .cr_error('HYBRID_BOUNDARY','Log-odds OOF inputs must be interior')
 design<-if(transform=='log_odds')matrix(stats::qlogis(p),nrow(p),ncol(p))else p;vary<-apply(design,2,function(v)diff(range(v))>0);active<-which(vary);constant<-which(!vary);w<-NULL;if(!is.null(weights)){raw<-unlist(weights,use.names=FALSE);if(length(raw)!=nrow(x)) .cr_error('HYBRID_WEIGHT','Weights must align with all rows');w<-.cr_numeric(raw[used],'used weights',vector_only=TRUE);if(any(w<0)||!any(w>0)) .cr_error('HYBRID_WEIGHT','Used weights need nonnegative values and positive support')}
 support<-if(is.null(w))rep(TRUE,length(used))else w>0;vary<-apply(design[support,,drop=FALSE],2,function(v)diff(range(v))>0);active<-which(vary);constant<-which(!vary)
 allowed<-c('input_scale','penalty','lambda_path','selected_lambda','l1_ratio','fit_intercept','scale','max_iter','tolerance');if(length(setdiff(names(spec),allowed))||length(setdiff(c('penalty','lambda_path','selected_lambda','fit_intercept','scale'),names(spec)))) .cr_error('HYBRID_META_MODEL','Actual penalized-logit specification required');metadata<-train;metadata$data_fingerprint<-.cr_hash(list(X=.ex_rows(design[,active,drop=FALSE]),outcomes=as.list(labels),row_ids=lapply(rows[used],function(r)r$row_id),weights=if(is.null(w))NULL else as.list(w)));kwargs<-spec[setdiff(names(spec),'input_scale')];kwargs$lambda_path<-.ex_vec(kwargs$lambda_path,'lambda_path')
 fitted<-do.call(fit_penalized_glm,c(list(design[,active,drop=FALSE],labels,feature_order=features[active],weights=w,target=target,training=metadata,model_id=paste0(model_id,'::meta'),model_version=model_version,context=context),kwargs))
 diagnostics<-list(meta_row_ids=lapply(rows[used],function(r)r$row_id),ignored_row_count=nrow(x)-length(used),fold_trace=checked$trace,meta_data_fingerprint=metadata$data_fingerprint,constant_base_ids=as.list(features[constant]),repeated_meta_entities=length(used)-length(unique(vapply(rows[used],function(r)r$entity_id,character(1)))),repeated_meta_groups=length(used)-length(unique(vapply(rows[used],function(r)r$group_id,character(1)))),meta_fit=fitted$diagnostics,uncertainty='NOT_ESTIMATED_POST_SELECTION',lineage_claim='DECLARED_HELD_OUT_PROVENANCE_CHECKED_NOT_AUTHENTICATED')
 model<-.cr_model(list(schema_version='1.0',model_id=model_id,model_version=model_version,method_id='hybrid.fit_stacked_pd',feature_order=as.list(features),parameters=list(kind='stacked_pd',input_scale=transform,active_indices=as.list(active-1L),constant_indices=as.list(constant-1L),constant_training_probabilities=as.list(p[which(support)[1],constant]),meta_model=fitted$model),preprocessing=list(training_only=TRUE,constant_rule='EXACT_CONSTANT_ON_USED_OOF_ROWS'),target=target,training=train,diagnostics=diagnostics,provenance=list(data_origin=if(is.null(train$data_origin))'USER_SUPPLIED'else train$data_origin,parameter_origin='ESTIMATED')))
 .cr_fit_result(model,'hybrid.fit_stacked_pd',diagnostics=diagnostics,context=context)
}
.hy_predict_stacked_pd<-function(fitted_model,X,feature_order,expected_target,context=NULL){model<-.cr_model(fitted_model);features<-.ex_ids(feature_order,'feature_order');if(model$method_id!='hybrid.fit_stacked_pd'||!identical(features,as.character(unlist(model$feature_order)))||!identical(.cr_hash(expected_target),.cr_hash(model$target))) .cr_error('HYBRID_MODEL','Frozen model, base order and target must agree');.ex_target(model$target,context);x<-.ex_matrix(X,'X');parameters<-model$parameters;if(ncol(x)!=length(features)||any(x<0|x>1)) .cr_error('HYBRID_PROBABILITY','Aligned probability matrix required');if(parameters$input_scale=='log_odds'&&any(x==0|x==1)) .cr_error('HYBRID_BOUNDARY','Log-odds predictions must be interior');design<-if(parameters$input_scale=='log_odds')matrix(stats::qlogis(x),nrow(x),ncol(x))else x;indices<-as.integer(unlist(parameters$active_indices))+1L;constant<-as.integer(unlist(parameters$constant_indices))+1L;meta<-parameters$meta_model;prediction<-predict_pd(meta,design[,indices,drop=FALSE],feature_order=features[indices],expected_target=expected_target,context=context);changed<-if(length(constant))sum(rowSums(sweep(x[,constant,drop=FALSE],2,unlist(parameters$constant_training_probabilities),'!='))>0)else 0L
 .cr_result(prediction$value,'classification.predict_pd','probability',context,diagnostics=list(model_id=model$model_id,model_version=model$model_version,prediction_family='stacked_pd',constant_base_departure_rows=changed,meta_model_id=meta$model_id),provenance=model$provenance,limitations='Frozen base order and target must match training. Constant bases have no fitted slope; departures from their training value are flagged. Meta coefficients are regression coefficients, not convex or causal weights.')}
